							throw new DecodeException("Packet decode failed:"
									+ "\nPacket ID: 0x" + Integer.toHexString(id) + ""
									+ "\nHandshake state: " + this.state
									+ "\nPacket size: " + length
									+ "\nReason: Unknown packet");
						packet.read(buf);
						in = packet;
					}
					break;
				}
				out.add(in);
